mapper.update:
UPDATE user_certification
SET status = #{status}, reason = #{reason}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT id, user_id, school, student_no, real_name, card_image, status, reason, create_time, update_time, deleted FROM user_certification WHERE deleted = 0
AND status = #{status}
ORDER BY create_time ASC LIMIT #{offset}, #{limit}
